package com.watchalign.mobile;
import org.junit.Test;
import static org.junit.Assert.*;
import java.util.*;
public class LuminousMeasurementTest {
    static double[][] rect(double angle){double c=Math.cos(angle),s=Math.sin(angle);double[][] p={{-2,-1},{2,-1},{2,1},{-2,1}};for(double[] q:p){double x=q[0],y=q[1];q[0]=c*x-s*y;q[1]=s*x+c*y;}return p;}
    @Test public void momentsMeasureRotationWithoutPixelBox(){assertEquals(12,LuminousGeometry.angleDifference(LuminousGeometry.angle(rect(Math.toRadians(12))),LuminousGeometry.angle(rect(0))),1e-10);}
    @Test public void filledRegionsMatchPercentage(){double[][] a=rect(0),b=rect(0);for(double[] p:b)p[0]+=.2;MarkerPolygonMismatch.Score s=MarkerPolygonMismatch.compare(a,b);assertEquals(s.extraPct+s.missingPct,s.mismatchPct,1e-12);assertEquals(s.extraArea,s.extraRegions().stream().mapToDouble(MarkerPolygonMismatch::area).sum(),1e-10);assertEquals(s.missingArea,s.missingRegions().stream().mapToDouble(MarkerPolygonMismatch::area).sum(),1e-10);}
    @Test public void localRingTransformIsReversibleAndDoesNotMutate(){ModelSpec.Marker m=new ModelSpec.Marker(9,ModelSpec.Shape.BATON,"nine",.75,0,.15,.06,0,0,0,0,0);double[] r={.01,-.005,.003,.012},snapshot=r.clone();double[][] p=rect(.1);double[][] q=LuminousGeometry.local(LuminousGeometry.placed(p,m,r),m,r);for(int i=0;i<p.length;i++)assertArrayEquals(p[i],q[i],1e-10);assertArrayEquals(snapshot,r,0);}
    @Test public void seedComponentRejectsBorderReflection(){byte[] px=new byte[40*40];Arrays.fill(px,(byte)220);assertNull(LuminousMarkerDetector.component(px,40,20,120));}
    @Test public void isolatedInnerIslandDoesNotAbsorbBrightMetalOrPrinting(){int n=50;byte[] p=new byte[n*n];for(int y=15;y<35;y++)for(int x=12;x<38;x++)p[y*n+x]=(byte)180;for(int y=5;y<9;y++)for(int x=5;x<45;x++)p[y*n+x]=(byte)255;double[][] q=LuminousMarkerDetector.component(p,n,25,110);assertNotNull(q);double[] c=LuminousGeometry.centroid(q);assertEquals(24.5,c[0],.01);assertEquals(24.5,c[1],.01);assertTrue(MarkerPolygonMismatch.area(q)<550);}
    @Test public void holeIsWithheldRatherThanFilledIntoPolygon(){int n=50;byte[] p=new byte[n*n];for(int y=10;y<40;y++)for(int x=10;x<40;x++)p[y*n+x]=(byte)180;for(int y=14;y<25;y++)for(int x=14;x<25;x++)p[y*n+x]=0;assertNull(LuminousMarkerDetector.component(p,n,30,100));}
    @Test public void smallEnclosedHoleIsNotSilentlyFilled(){int n=50;byte[] p=new byte[n*n];for(int y=10;y<40;y++)for(int x=10;x<40;x++)p[y*n+x]=(byte)180;p[15*n+15]=0;assertNull(LuminousMarkerDetector.component(p,n,30,100));}
    @Test public void deepNotchIsWithheldInsteadOfConvexFilling(){int n=50;byte[] p=new byte[n*n];for(int y=10;y<40;y++)for(int x=10;x<40;x++)p[y*n+x]=(byte)180;for(int y=10;y<15;y++)for(int x=14;x<17;x++)p[y*n+x]=0;assertNull(LuminousMarkerDetector.component(p,n,30,100));}
    @Test public void uncertainBoundaryNeverProducesPercentage(){ModelSpec.Marker m=new ModelSpec.Marker(6,ModelSpec.Shape.BATON,"six",.75,0,.15,.06,0,0,0,0,0);LuminousMarkerDetector.Detection d=new LuminousMarkerDetector.Detection(6);d.reason="uncertain polished reflection";LuminousMeasurement.Marker q=new LuminousMeasurement.Marker(m,d,rect(0));assertFalse(q.assessed());assertNull(q.score);assertTrue(q.description().startsWith("Not assessed"));assertFalse(q.displayPolygon().trusted());}
    @Test public void absentIndependentReferenceCannotBeScored(){ModelSpec.Marker m=new ModelSpec.Marker(6,ModelSpec.Shape.BATON,"six",.75,0,.15,.06,0,0,0,0,0);LuminousMarkerDetector.Detection d=new LuminousMarkerDetector.Detection(6);d.reason="measured";d.polygon=rect(0);LuminousMeasurement.Marker q=new LuminousMeasurement.Marker(m,d,null);assertFalse(q.assessed());assertTrue(q.reason.contains("reference"));}
}
